@DisplayName("카페 키오스크")
class CafeKioskTest {

    private static final LocalDateTime 개점직전 = LocalDateTime.of(2026, 9, 9, 9, 59);
    private static final LocalDateTime 개점정각 = LocalDateTime.of(2026, 9, 9, 10, 0);
    private static final LocalDateTime 마감직전 = LocalDateTime.of(2026, 9, 9, 21, 59);
    private static final LocalDateTime 마감정각 = LocalDateTime.of(2026, 9, 9, 22, 0);

    private CafeKiosk cafeKiosk;

    @BeforeEach
    void setUp() {
        cafeKiosk = new CafeKiosk();
    }

    @Nested
    @DisplayName("음료를 담을 때")
    class Add {

        @DisplayName("한 잔을 담으면 주문 목록에 한 개가 들어간다")
        @Test
        void one() {
            // given
            Americano americano = new Americano();

            // when
            cafeKiosk.add(americano, 1);

            // then
            assertThat(cafeKiosk.getBeverages()).hasSize(1);
        }

        @DisplayName("0잔을 담으면 예외가 난다")
        @Test
        void zero() {
            // given
            Americano americano = new Americano();

            // when & then
            assertThatThrownBy(() -> cafeKiosk.add(americano, 0))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessage("음료는 1잔 이상 주문하실 수 있습니다.");
        }
    }

    @Nested
    @DisplayName("주문을 생성할 때")
    class CreateOrder {

        @DisplayName("마감 시각 정각에는 주문할 수 없다")
        @Test
        void atCloseTime() {
            // given
            cafeKiosk.add(new Americano(), 1);

            // when & then
            assertThatThrownBy(() -> cafeKiosk.createOrder(마감정각))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessage("주문 시간이 아닙니다.");
        }
    }
}
